<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rspec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RspecJunitFormatter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> junit.xml</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flakemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> junit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> junit.xml</span></span>
